from pathlib import Path

# Dedicated V3.9 runtime pool: never falls back to the application owner/shared DB.
db_v39 = Path('server/lib/disruption/db_v39.ts')
db_v39.write_text('''import { Pool } from "pg";\n\nlet runtimePool: Pool | null = null;\n\nfunction requireV39RuntimeUrl(): string {\n  const url = String(process.env.V39_DATABASE_RUNTIME_URL ?? "").trim();\n  if (!url) {\n    throw new Error("V39_DATABASE_RUNTIME_URL_REQUIRED: V3.9 clean-schema runtime DB is not configured");\n  }\n  return url;\n}\n\nexport function getV39Pool(): Pool {\n  if (!runtimePool) runtimePool = new Pool({ connectionString: requireV39RuntimeUrl() });\n  return runtimePool;\n}\n\n/**\n * Lazy proxy so importing a V3.9 module does not crash the ordinary Travnr app\n * when V3.9 is intentionally unconfigured. The first V3.9 DB operation fails\n * closed unless V39_DATABASE_RUNTIME_URL is present.\n */\nexport const v39Pool = new Proxy({} as Pool, {\n  get(_target, prop) {\n    const active = getV39Pool() as any;\n    const value = active[prop as any];\n    return typeof value === "function" ? value.bind(active) : value;\n  },\n});\n''')

replacements = {
  'server/routes_v3.ts': [('import { pool } from "./db";', 'import { v39Pool as pool } from "./lib/disruption/db_v39";')],
  'server/lib/disruption/rawIngress_v3.ts': [('import { pool } from "../../db";', 'import { v39Pool as pool } from "./db_v39";')],
  'server/lib/disruption/flightInstanceCanonical_v3.ts': [('import { pool } from "../../db";', 'import { v39Pool as pool } from "./db_v39";')],
  'server/lib/disruption/flightDataPrePostStore_v3.ts': [('import { db, pool } from "../../db";', 'import { db } from "../../db";\nimport { v39Pool as pool } from "./db_v39";')],
  'server/lib/disruption/adbCollectionController_v3.ts': [('import { pool } from "../../db";', 'import { v39Pool as pool } from "./db_v39";')],
  'server/lib/disruption/phase6SegmentActivation_v39.ts': [('import { pool } from "../../db";', 'import { v39Pool as pool } from "./db_v39";')],
  'server/lib/disruption/phase6SafetyWatchdog_v39.ts': [('import { pool } from "../../db";', 'import { v39Pool as pool } from "./db_v39";')],
  'server/lib/disruption/airborneMaterializer_v39.ts': [('import { pool } from "../../db";', 'import { v39Pool as pool } from "./db_v39";')],
  'server/lib/disruption/probeExecution_v39.ts': [('import { pool } from "../../db";', 'import { v39Pool as pool } from "./db_v39";')],
  'server/lib/disruption/historicalFeatureStore_v3.ts': [('import { pool } from "../../db";', 'import { v39Pool as pool } from "./db_v39";')],
  'server/lib/disruption/fidsCensus_v3.ts': [('import { pool } from "../../db";', 'import { v39Pool as pool } from "./db_v39";')],
  'server/lib/disruption/gates_v3.ts': [('import { pool } from "../../db";', 'import { v39Pool as pool } from "./db_v39";')],
  'scripts/v39_phase6_start_owner_v39.ts': [('import { pool } from "../server/db";', 'import { v39Pool as pool } from "../server/lib/disruption/db_v39";')],
  'scripts/v39_phase6_pause_v39.ts': [('import { pool } from "../server/db";', 'import { v39Pool as pool } from "../server/lib/disruption/db_v39";')],
  'scripts/v39_probe_stage1_owner_v39.ts': [('import { pool } from "../server/db";', 'import { v39Pool as pool } from "../server/lib/disruption/db_v39";')],
  'scripts/v39_probe_stage2_owner_v39.ts': [('import { pool } from "../server/db";', 'import { v39Pool as pool } from "../server/lib/disruption/db_v39";')],
  'scripts/v39_gate5_owner_v39.ts': [('import { pool } from "../server/db";', 'import { v39Pool as pool } from "../server/lib/disruption/db_v39";')],
  'scripts/anchor_probe.ts': [('import { pool } from "../server/db";', 'import { v39Pool as pool } from "../server/lib/disruption/db_v39";')],
  'scripts/build_stratified_catalog.ts': [('import { pool, applyBootMigrations } from "../server/db";', 'import { applyBootMigrations } from "../server/db";\nimport { v39Pool as pool } from "../server/lib/disruption/db_v39";')],
  'scripts/credit_canary.ts': [('import { pool } from "../server/db";', 'import { v39Pool as pool } from "../server/lib/disruption/db_v39";')],
  'scripts/check_collection_health.ts': [('import { pool } from "../server/db";', 'import { v39Pool as pool } from "../server/lib/disruption/db_v39";')],
  'scripts/export_flight_data.ts': [('import { pool } from "../server/db";', 'import { v39Pool as pool } from "../server/lib/disruption/db_v39";')],
  'scripts/backfill_flight_data_pre_post.ts': [('import { pool } from "../server/db";', 'import { v39Pool as pool } from "../server/lib/disruption/db_v39";')],
}

for filename, pairs in replacements.items():
    p = Path(filename)
    text = p.read_text()
    for old, new in pairs:
        if old not in text:
            raise SystemExit(f'missing expected import in {filename}: {old}')
        text = text.replace(old, new, 1)
    p.write_text(text)

# Security verifier keeps owner-role inspection on DATABASE_URL but uses the
# restricted V3.9 pool for clean-schema runtime proofs.
p = Path('scripts/v39_security_verify_v39.ts')
text = p.read_text()
old = 'const {pool}=await import("../server/db");const tomb=await pool.query(`SELECT surface,record_id,content_hash,expired_at FROM clean.retention_tombstone WHERE expired_at<=now() ORDER BY expired_at ASC`);'
new = 'const {v39Pool:pool}=await import("../server/lib/disruption/db_v39");const tomb=await pool.query(`SELECT surface,record_id,content_hash,expired_at FROM clean.retention_tombstone WHERE expired_at<=now() ORDER BY expired_at ASC`);'
if old not in text: raise SystemExit('security verifier retention dynamic import not found')
text = text.replace(old, new, 1)
old = 'try{const {pool}=await import("../server/db");await pool.query("SELECT 1 FROM clean.adb_incident_stop WHERE resolved=false LIMIT 1");'
new = 'try{const {v39Pool:pool}=await import("../server/lib/disruption/db_v39");await pool.query("SELECT 1 FROM clean.adb_incident_stop WHERE resolved=false LIMIT 1");'
if old not in text: raise SystemExit('security verifier incident dynamic import not found')
text = text.replace(old, new, 1)
p.write_text(text)

# Rebuild provisioning around a V3.9-only role and the actual current database,
# not the historical Neon-wide DATABASE_RUNTIME_URL assumption.
p = Path('scripts/provision_runtime_role_v39.ts')
p.write_text('''/** Provision/reconcile the dedicated least-privilege V3.9 clean-schema runtime role. */\nimport { randomBytes } from "crypto";\nimport { readFileSync, writeFileSync } from "fs";\nimport { join } from "path";\nimport { Pool } from "pg";\n\nconst ROLE = "travnr_v39_runtime";\nconst ENV_PATH = join(process.cwd(), ".env");\n\nfunction escapeIdent(s: string): string { return `"${s.replace(/"/g, `""`)}"`; }\nfunction escapeLiteral(s: string): string { return s.replace(/'/g, `''`); }\nfunction upsertEnvVar(src: string, key: string, value: string): string {\n  const line = `${key}=${value}`;\n  const re = new RegExp(`^${key}=.*$`, "m");\n  if (re.test(src)) return src.replace(re, () => line);\n  return src.endsWith("\\n") || src.length === 0 ? `${src}${line}\\n` : `${src}\\n${line}\\n`;\n}\n\nasync function main(): Promise<void> {\n  const ownerUrl = process.env.DATABASE_URL;\n  if (!ownerUrl) throw new Error("DATABASE_URL owner connection is required");\n  const owner = new Pool({ connectionString: ownerUrl });\n  try {\n    const meta = await owner.query("SELECT current_database() AS db, current_user AS owner_role");\n    const dbName = String(meta.rows[0]?.db ?? "");\n    const ownerRole = String(meta.rows[0]?.owner_role ?? "");\n    if (!dbName || !ownerRole) throw new Error("unable to resolve current database/owner role");\n\n    const password = randomBytes(32).toString("base64url");\n    const exists = await owner.query("SELECT 1 FROM pg_roles WHERE rolname=$1", [ROLE]);\n    if (exists.rowCount === 0) {\n      await owner.query(`CREATE ROLE ${escapeIdent(ROLE)} WITH LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT PASSWORD '${escapeLiteral(password)}'`);\n      console.log(`role created: ${ROLE}`);\n    } else {\n      await owner.query(`ALTER ROLE ${escapeIdent(ROLE)} WITH LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT PASSWORD '${escapeLiteral(password)}'`);\n      console.log(`role reconciled: ${ROLE}`);\n    }\n\n    // Remove any direct table grants left from an older use of this role.\n    const oldGrants = await owner.query(\n      `SELECT DISTINCT table_schema, table_name FROM information_schema.role_table_grants WHERE grantee=$1`,\n      [ROLE],\n    );\n    for (const row of oldGrants.rows) {\n      await owner.query(`REVOKE ALL PRIVILEGES ON TABLE ${escapeIdent(String(row.table_schema))}.${escapeIdent(String(row.table_name))} FROM ${escapeIdent(ROLE)}`);\n    }\n\n    await owner.query(`GRANT CONNECT ON DATABASE ${escapeIdent(dbName)} TO ${escapeIdent(ROLE)}`);\n    await owner.query(`GRANT USAGE ON SCHEMA clean TO ${escapeIdent(ROLE)}`);\n    await owner.query(`GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA clean TO ${escapeIdent(ROLE)}`);\n    await owner.query(`GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA clean TO ${escapeIdent(ROLE)}`);\n    await owner.query(`ALTER DEFAULT PRIVILEGES FOR ROLE ${escapeIdent(ownerRole)} IN SCHEMA clean GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO ${escapeIdent(ROLE)}`);\n    await owner.query(`ALTER DEFAULT PRIVILEGES FOR ROLE ${escapeIdent(ownerRole)} IN SCHEMA clean GRANT USAGE, SELECT ON SEQUENCES TO ${escapeIdent(ROLE)}`);\n\n    const attr = await owner.query("SELECT rolsuper, rolcreatedb, rolcreaterole, rolcanlogin FROM pg_roles WHERE rolname=$1", [ROLE]);\n    const a = attr.rows[0];\n    if (!a || a.rolsuper || a.rolcreatedb || a.rolcreaterole || !a.rolcanlogin) throw new Error("runtime role attribute verification failed");\n    const grants = await owner.query(\n      `SELECT table_schema AS s, table_name AS t,string_agg(DISTINCT privilege_type,',' ORDER BY privilege_type) AS p FROM information_schema.role_table_grants WHERE grantee=$1 GROUP BY 1,2 ORDER BY 1,2`,\n      [ROLE],\n    );\n    const allowed = new Set(["SELECT", "INSERT", "UPDATE", "DELETE"]);\n    if (!grants.rows.length) throw new Error("runtime role has no clean table grants");\n    for (const row of grants.rows) {\n      if (row.s !== "clean") throw new Error(`grant outside clean schema: ${row.s}.${row.t}`);\n      for (const privilege of String(row.p).split(",")) if (!allowed.has(privilege)) throw new Error(`excess privilege ${privilege}@${row.s}.${row.t}`);\n    }\n\n    const u = new URL(ownerUrl);\n    u.username = ROLE;\n    u.password = password;\n    if (!u.searchParams.get("sslmode")) u.searchParams.set("sslmode", "require");\n    const runtimeUrl = u.toString();\n    const runtime = new Pool({ connectionString: runtimeUrl });\n    try {\n      const who = await runtime.query("SELECT current_user AS u");\n      if (who.rows[0]?.u !== ROLE) throw new Error("runtime connection role mismatch");\n      await runtime.query("SELECT 1 FROM clean.retention_tombstone LIMIT 1");\n    } finally { await runtime.end().catch(() => undefined); }\n\n    const tomb = await owner.query("SELECT to_regclass('clean.retention_tombstone') AS c");\n    const evidence = { verified: true, verifiedDate: new Date().toISOString().slice(0,10), tls: /sslmode=/i.test(runtimeUrl), role: ROLE, grants: ["CLEAN_SCHEMA_DML", "CLEAN_SEQUENCE_USAGE"], auditLogging: tomb.rows[0]?.c === "clean.retention_tombstone" };\n    let env = "";\n    try { env = readFileSync(ENV_PATH, "utf8"); } catch { env = ""; }\n    env = upsertEnvVar(env, "V39_DATABASE_RUNTIME_URL", runtimeUrl);\n    env = upsertEnvVar(env, "V39_DB_ROLE_EVIDENCE", `'${JSON.stringify(evidence)}'`);\n    writeFileSync(ENV_PATH, env, { mode: 0o600 });\n    console.log(`provision result=PASS role=${ROLE} clean_tables=${grants.rows.length} (secret URL written to ignored .env only)`);\n  } finally { await owner.end().catch(() => undefined); }\n}\n\nmain().catch((e) => { console.error(`provision FAILED: ${e?.message ?? e}`); process.exit(1); });\n''')

# Static regression proof.
t = Path('tests/v39_db_separation_v39.test.ts')
t.write_text('''import { describe, expect, it } from "vitest";\nimport { readFileSync } from "fs";\n\nconst read = (p: string) => readFileSync(p, "utf8");\nconst active = [\n  "server/routes_v3.ts",\n  "server/lib/disruption/rawIngress_v3.ts",\n  "server/lib/disruption/flightInstanceCanonical_v3.ts",\n  "server/lib/disruption/adbCollectionController_v3.ts",\n  "server/lib/disruption/phase6SegmentActivation_v39.ts",\n  "server/lib/disruption/phase6SafetyWatchdog_v39.ts",\n  "server/lib/disruption/airborneMaterializer_v39.ts",\n  "server/lib/disruption/probeExecution_v39.ts",\n  "server/lib/disruption/historicalFeatureStore_v3.ts",\n  "server/lib/disruption/fidsCensus_v3.ts",\n  "server/lib/disruption/gates_v3.ts",\n  "scripts/v39_phase6_start_owner_v39.ts",\n  "scripts/v39_phase6_pause_v39.ts",\n  "scripts/v39_probe_stage1_owner_v39.ts",\n  "scripts/v39_probe_stage2_owner_v39.ts",\n  "scripts/v39_gate5_owner_v39.ts",\n  "scripts/anchor_probe.ts",\n  "scripts/credit_canary.ts",\n  "scripts/check_collection_health.ts",\n  "scripts/export_flight_data.ts",\n  "scripts/backfill_flight_data_pre_post.ts",\n];\n\ndescribe("V3.9 dedicated DB runtime separation", () => {\n  it("uses a dedicated fail-closed V39_DATABASE_RUNTIME_URL owner", () => {\n    const src = read("server/lib/disruption/db_v39.ts");\n    expect(src).toContain("V39_DATABASE_RUNTIME_URL");\n    expect(src).toContain("V39_DATABASE_RUNTIME_URL_REQUIRED");\n    expect(src).not.toContain("process.env.DATABASE_URL");\n    expect(src).not.toContain("DATABASE_RUNTIME_URL ||");\n  });\n  it("keeps the ordinary Travnr shared pool unchanged", () => {\n    const src = read("server/db.ts");\n    expect(src).toContain("process.env.DATABASE_RUNTIME_URL || process.env.DATABASE_URL");\n  });\n  it("routes active V3.9 raw-pool owners away from the shared app pool", () => {\n    for (const file of active) {\n      const src = read(file);\n      expect(src, file).toContain("db_v39");\n      expect(src, file).not.toMatch(/import\\s*\\{\\s*pool\\s*\\}\\s*from\\s*[\"'][^\"']*server\\/db[\"']/);\n      expect(src, file).not.toMatch(/import\\s*\\{\\s*pool\\s*\\}\\s*from\\s*[\"']\\.\\.\\/\\.\\.\\/db[\"']/);\n    }\n  });\n  it("keeps boot migrations on owner DB and provisions the V3.9-specific secret", () => {\n    expect(read("server/db.ts")).toContain("migrationPool");\n    const provision = read("scripts/provision_runtime_role_v39.ts");\n    expect(provision).toContain("V39_DATABASE_RUNTIME_URL");\n    expect(provision).toContain("travnr_v39_runtime");\n    expect(provision).not.toContain("DATABASE_RUNTIME_URL\", runtimeUrl");\n    expect(provision).not.toContain("DATABASE neondb");\n  });\n});\n''')
